  "saoi_search_products": {
    "method": "POST",
    "path": "/api/market/search",
    "summary": "Search and rank Irish financial products for the customer’s own figures",
    "description": "Ranks the products in one category (savings, deposit, mortgage, loan, credit_card, current_account) with the figures for the amounts given: interest after DIRT for savings and deposits, monthly repayment and total cost for mortgages and loans. Default objective: highest net return for savings and deposits, lowest total cost for debt; `objective` changes it and the result states the basis. Top 5 by default (`limit` up to 25). Every product carries its source (`bank` or `ccpc`), when it was checked and last changed, the CCPC attribution where it applies, the fields the source does not give (never treated as zero), its deposit guarantee, and eligibility to check. Providers that operate in Ireland only. Information, not advice: results are ranked by a stated objective, for the inputs given. Unauthenticated. Nothing sent is stored, except that a plan is held for 24 hours behind a single-use link so it can be opened in the Saoi app, then deleted unless opened.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "category": {
          "type": "string",
          "enum": [
            "savings",
            "deposit",
            "mortgage",
            "loan",
            "credit_card",
            "current_account"
          ],
          "description": "`savings`: regular monthly saving. `deposit`: a lump sum (instant access, notice, fixed term). `mortgage`, `loan`, `credit_card`, `current_account`."
        },
        "amount": {
          "type": "number",
          "minimum": 0,
          "maximum": 100000000,
          "description": "Savings and deposits: the lump sum. Loans: the amount to borrow. Cards: the balance carried."
        },
        "monthlyAmount": {
          "type": "number",
          "minimum": 0,
          "maximum": 100000000,
          "description": "Savings: what is paid in each month."
        },
        "horizonMonths": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "maximum": 480,
          "description": "Savings and deposits: how long until the money is needed. Default 12. No fixed term longer than this is shown."
        },
        "access": {
          "type": "string",
          "enum": [
            "instant",
            "notice",
            "fixed_term",
            "any"
          ],
          "description": "Savings and deposits: only this kind of access. Default any."
        },
        "maxNoticeDays": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1000
        },
        "providers": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^[a-z0-9_]{2,40}$"
          },
          "maxItems": 30
        },
        "buyerType": {
          "type": "string",
          "enum": [
            "first_time_buyer",
            "mover",
            "switcher"
          ],
          "description": "Mortgages: whose list to search. Default first_time_buyer."
        },
        "propertyValue": {
          "type": "number",
          "minimum": 0,
          "maximum": 100000000,
          "description": "Mortgages: the property’s value."
        },
        "loanAmount": {
          "type": "number",
          "minimum": 0,
          "maximum": 100000000,
          "description": "Mortgages: the amount to borrow."
        },
        "termYears": {
          "type": "integer",
          "minimum": 1,
          "maximum": 40,
          "description": "Mortgages: the term. Default 30."
        },
        "ber": {
          "type": "string",
          "pattern": "^([A-G][1-3]?|Exempt)$/i",
          "description": "Mortgages: the BER. Without it, BER-specific (green) rates are left out and counted."
        },
        "termMonths": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "maximum": 480,
          "description": "Loans: the term to repay over. Default 60."
        },
        "purpose": {
          "type": "string",
          "enum": [
            "personal",
            "car",
            "home_improvement",
            "energy_upgrade",
            "holiday",
            "student"
          ],
          "description": "Loans: only loans for this purpose."
        },
        "objective": {
          "type": "string",
          "enum": [
            "highest_net_return",
            "easiest_access",
            "lowest_total_cost",
            "lowest_monthly_repayment"
          ],
          "description": "What to rank by. Default `highest_net_return` for savings and deposits, `lowest_total_cost` for the rest. `easiest_access` applies to savings and deposits; `lowest_monthly_repayment` to mortgages and loans."
        },
        "limit": {
          "type": "integer",
          "minimum": 1,
          "maximum": 25,
          "description": "How many results. Default 5."
        }
      },
      "required": [
        "category"
      ],
      "description": "What to compare and for which figures."
    }
  },
